// Stand-in for @minecraft/server-ui: forms record what they showed and answer with UI.answers (a queue).
export const UI = { shown: [], answers: [] };
class Form {
  constructor() { this.items = []; }
  title(t) { this.t = t; return this; }
  body(b) { this.b = b; return this; }
  button(x) { this.items.push(["button", x]); return this; }
  button1(x) { this.items.push(["button1", x]); return this; }
  button2(x) { this.items.push(["button2", x]); return this; }
  slider(l, min, max, o) { if (typeof o !== "object") throw new Error("slider options"); this.items.push(["slider", l, o.defaultValue]); return this; }
  toggle(l, o) { if (typeof o !== "object") throw new Error("toggle options"); this.items.push(["toggle", l, o.defaultValue]); return this; }
  async show(p) { UI.shown.push({ title: this.t, body: this.b, items: this.items }); return UI.answers.shift() ?? { canceled: true }; }
}
export class ActionFormData extends Form {}
export class ModalFormData extends Form {}
export class MessageFormData extends Form {}
